import json,random,subprocess,sys,os
random.seed(98765)
def lpm(fib,addr):
 x=int(addr,16);best=(-1,None)
 for (p,l),h in fib.items():
  if l==0 or (x>>(128-l))==(p>>(128-l)):
   if l>best[0]:best=(l,h)
 return best[1]
def run(req,debug=False):
 env=dict(os.environ)
 if debug:env['SCAMP_DEBUG_VALIDATE']='1'
 p=subprocess.run(['python3','run.py'],input=json.dumps(req).encode(),stdout=subprocess.PIPE,stderr=subprocess.PIPE,env=env)
 if p.returncode:
  print('RC',p.returncode,p.stderr.decode());sys.exit(1)
 return json.loads(p.stdout),p.stderr.decode()
lengths=list(range(0,20))+[21,22,23,28,29,40,47,48,58,59,60,61,62,63,64,65,66,67,68,96,118,119,120,121,124,125,126,127,128]
for trial in range(300):
 ops=[]; expected=[]; loads_exp=[]; snapshots_fib=[]; fib={}
 # prefix pool cluster
 bases=[random.getrandbits(128) for _ in range(random.randint(1,20))]
 # do random ops including saves and loads based on saved count
 nsaves=random.randint(0,3)
 # create phases
 for phase in range(nsaves+1):
  for i in range(random.randint(0,100)):
   if random.random()<0.6:
    l=random.choice(lengths)
    if random.random()<.2:l=random.randint(0,128)
    base=random.choice(bases)
    p=0 if l==0 else (base>>(128-l))<<(128-l)
    h=random.randrange(4194303)
    host=random.getrandbits(128-l) if l<128 else 0
    ops.append(['put',f'{p|host:032x}',l,h]);fib[(p,l)]=h
   else:
    q=f'{random.getrandbits(128):032x}'
    ops.append(['query',[q]]);expected.append(lpm(fib,q))
  if phase<nsaves:
   ops.append(['save']);snapshots_fib.append(dict(fib))
   # query current image after load
   idx=len(snapshots_fib)-1
   if random.random()<.8:
    ops.append(['load_saved',idx]);loads_exp.append(True)
    for _ in range(random.randint(0,6)):
     q=f'{random.getrandbits(128):032x}'
     ops.append(['image_query',[q]]);expected.append(lpm(snapshots_fib[idx],q))
 # optionally load earlier snapshots and query
 for _ in range(random.randint(0,10)):
  if not snapshots_fib:break
  idx=random.randrange(len(snapshots_fib))
  ops.append(['load_saved',idx]);loads_exp.append(True)
  for j in range(random.randint(0,5)):
   q=f'{random.getrandbits(128):032x}'
   ops.append(['image_query',[q]]);expected.append(lpm(snapshots_fib[idx],q))
 # live updates after last load then query image unaffected and live changed
 for i in range(random.randint(0,30)):
  l=random.choice(lengths);base=random.choice(bases)
  p=0 if l==0 else (base>>(128-l))<<(128-l);h=random.randrange(4194303)
  host=random.getrandbits(128-l) if l<128 else 0
  ops.append(['put',f'{p|host:032x}',l,h]);fib[(p,l)]=h
 for _ in range(random.randint(0,10)):
  q=f'{random.getrandbits(128):032x}'
  if random.random()<.5:
   ops.append(['query',[q]]);expected.append(lpm(fib,q))
  else:
   ops.append(['image_query',[q]]);expected.append(lpm(snapshots_fib[idx],q) if snapshots_fib else None)
 # final query all random
 for _ in range(20):
  q=f'{random.getrandbits(128):032x}'
  ops.append(['query',[q]]);expected.append(lpm(fib,q))
 req={'cases':[{'ops':ops}]}
 r,err=run(req,True)
 if err.strip():
  print('validator err trial',trial,err[:500]);sys.exit(1)
 res=r['results'][0]
 if res['answers']!=expected:
  print('answer mismatch trial',trial)
  for i,(a,b) in enumerate(zip(res['answers'],expected)):
   if a!=b:print(i,a,b);break
  sys.exit(1)
 if res['loads']!=loads_exp or not all(res['loads']):
  print('loads mismatch',trial,res['loads'],loads_exp);sys.exit(1)
 if len(res['snapshots'])!=nsaves:
  print('snapshot count');sys.exit(1)
print('multi random ok')
